/* V200 — Mantém identificação e ano vazios até o processamento de XML, SPED ou EFD.
   O simulador roda em iframe isolado, preservando as rotinas do Classificador. */
(() => {
  const origem = '';
  const decodificar = b64 => new TextDecoder().decode(Uint8Array.from(atob(b64), c => c.charCodeAt(0)));
  const tabs = document.querySelector('.tabs');
  if (!tabs || document.getElementById('tab-exclusao-ibs-cbs')) return;
  const botao = document.createElement('button');
  botao.className = 'tab'; botao.id = 'tab-exclusao-ibs-cbs';
  botao.type = 'button'; botao.textContent = 'Exclusão IBS/CBS';
  const painel = document.createElement('section');
  painel.id = 'exclusao-ibs-cbs'; painel.className = 'panel';
  painel.innerHTML = '<div class="card"><h2>Exclusão da IBS e da CBS da base de cálculo do ICMS</h2><p class="hint">Simulador integrado — processamento local no navegador.</p></div>';
  const quadro = document.createElement('iframe');
  quadro.title = 'Simulador de Exclusão IBS/CBS'; quadro.className = 'v199-simulador';
  quadro.setAttribute('sandbox', 'allow-scripts allow-forms allow-downloads allow-same-origin');
  quadro.srcdoc = decodificar(origem); painel.append(quadro);
  tabs.append(botao); document.querySelector('main.wrap').append(painel);
  const abrir = () => { document.querySelectorAll('.tabs .tab').forEach(x => x.classList.toggle('active', x === botao)); document.querySelectorAll('main.wrap > .panel').forEach(x => x.classList.toggle('active', x === painel)); window.scrollTo({top:0,behavior:'smooth'}); };
  botao.addEventListener('click', abrir);
  const estilo = document.createElement('style');
  estilo.textContent = '.v199-simulador{display:block;width:100%;min-height:1200px;border:0;background:#fff;border-radius:10px}.panel#exclusao-ibs-cbs{padding:0;background:transparent}'; document.head.append(estilo);
})();
